193	// seedCopier is the ImageCopier of the tests. It models the three registries the
194	// way the real ones behave: the upstream (reached only while the port-forward is
195	// open, no authentication), docker-hosted (admin) and docker-proxy (bench-pull, a
196	// read pulls the image through and caches it). Hosted and proxy contents are
197	// mirrored into the fake Nexus listing. It reads the layout Seed wrote, so a copy
198	// puts the digest of the image the layout says, and a wrong reference to the
199	// layout shows.
200	type seedCopier struct {
201		t     *testing.T
202		log   *orderLog
203		fwd   *fakeForwarder
204		nexus *fakeNexus
205		p     *Params
206		tmp   string
207	
208		admin, pull Credentials
209	
210		index map[string]refInfo // imageArg -> what it is
211	
212		upstream, hosted, proxyCache map[string]string // "name:tag" -> manifest digest
213		listing                      map[string][]fakeComponent
214		hidden                       map[string]bool // repositories whose listing is not published yet
215	
216		copies    []copyCall
217		digests   []digestCall
218		ociCopies int
219	
220		// copyErr, when set, runs at the start of the n-th Copy (1-based); a non-nil
221		// answer is the result of the Copy.
222		copyErr func(n int, c copyCall) error
223		// digestErr, when set, runs at the start of every ManifestDigest.
224		digestErr func(c digestCall) error
225	}
