277	// authorize checks the credentials offered to a registry.
278	func (c *seedCopier) authorize(where string, creds *Credentials) error {
279		var want *Credentials
280		switch where {
281		case whereHosted:
282			want = &c.admin
283		case whereProxy:
284			want = &c.pull
285		}
286		if !sameCreds(creds, want) {
287			c.t.Errorf("the %s registry was offered the wrong credentials", where)
288			return refusedImage()
289		}
290		return nil
291	}
