293	// reach fails the way a closed port-forward does.
294	func (c *seedCopier) reach(where string) error {
295		if where == whereUpstream && !c.fwd.active {
296			c.t.Errorf("the upstream was reached while the port-forward is not open")
297			return &BenchError{Kind: RegistryUnreachable, Cause: "connection refused", Check: "start the port-forward"}
298		}
299		return nil
300	}
