302	// read returns the manifest digest of ref the way a registry (or a layout) would.
303	func (c *seedCopier) read(ref ImageRef, creds *Credentials) (string, error) {
304		if ref.Transport == "oci" {
305			return c.readLayout(ref)
306		}
307		info, ok := c.lookup(ref)
308		if !ok || ref.Transport != "docker" {
309			c.t.Errorf("read of %s: not a reference of the data set", imageArg(ref))
310			return "", absentImage()
311		}
312		if err := c.reach(info.where); err != nil {
313			return "", err
314		}
315		if err := c.authorize(info.where, creds); err != nil {
316			return "", err
317		}
318		nt := nameTag(info.img)
319		switch info.where {
320		case whereUpstream:
321			if d, ok := c.upstream[nt]; ok {
322				return d, nil
323			}
324		case whereHosted:
325			if d, ok := c.hosted[nt]; ok {
326				return d, nil
327			}
328		case whereProxy:
329			if !info.img.PullThrough {
330				c.t.Errorf("F9: %s was read through docker-proxy, which caches it: only PullThrough images may be", nt)
331			}
332			if d, ok := c.proxyCache[nt]; ok {
333				return d, nil
334			}
335			if d, ok := c.upstream[nt]; ok {
336				c.preload(whereProxy, info.img, d)
337				return d, nil
338			}
339		}
340		return "", absentImage()
341	}
