474	// ---- the state of the registries
475	
476	// preload puts an image, with a digest, in a registry as an earlier run left it.
477	func (c *seedCopier) preload(where string, img DatasetImage, digest string) {
478		nt := nameTag(img)
479		switch where {
480		case whereUpstream:
481			c.upstream[nt] = digest
482		case whereHosted:
483			c.hosted[nt] = digest
484			c.setComponent(dockerHostedRepository, img, digest)
485		case whereProxy:
486			c.proxyCache[nt] = digest
487			c.setComponent(dockerProxyRepository, img, digest)
488		}
489	}
490	
491	// preloadAll is the registries as a complete seed leaves them.
492	func (c *seedCopier) preloadAll() {
493		for _, img := range Dataset() {
494			switch img.Location {
495			case LocationHosted:
496				c.preload(whereHosted, img, img.Digest)
497			case LocationUpstream:
498				c.preload(whereUpstream, img, img.Digest)
499				if img.PullThrough {
500					c.preload(whereProxy, img, img.Digest)
501				}
502			}
503		}
504	}
505	
506	// removeUpstream takes an image out of the upstream.
507	func (c *seedCopier) removeUpstream(img DatasetImage) { delete(c.upstream, nameTag(img)) }
508	
509	func (c *seedCopier) setComponent(repo string, img DatasetImage, digest string) {
510		comp := fakeComponent{Name: img.Name, Version: img.Tag, Digest: digest}
511		list := c.listing[repo]
512		if i := slices.IndexFunc(list, func(x fakeComponent) bool { return x.Name == comp.Name && x.Version == comp.Version }); i >= 0 {
513			list[i] = comp
514		} else {
515			list = append(list, comp)
516		}
517		c.listing[repo] = list
