616	func (e *seedEnv) runWith(ctx context.Context) (SeedResult, error) {
617		e.t.Helper()
618		var out io.Writer = e.out
619		if e.nilOut {
620			out = nil
621		}
622		e.runs++
623		res, err := Seed(ctx, e.deps, e.b.nexus.URL(), e.p, out)
624		e.checkInvariants(err)
