193	// seedCopier is the ImageCopier of the tests. It models the three registries the
194	// way the real ones behave: the upstream (reached only while the port-forward is
195	// open, no authentication), docker-hosted (admin) and docker-proxy (bench-pull, a
196	// read pulls the image through and caches it). Hosted and proxy contents are
197	// mirrored into the fake Nexus listing. It reads the layout Seed wrote, so a copy
198	// puts the digest of the image the layout says, and a wrong reference to the
199	// layout shows.
200	type seedCopier struct {
201		t     *testing.T
202		log   *orderLog
203		fwd   *fakeForwarder
204		nexus *fakeNexus
205		p     *Params
206		tmp   string
