229	func absentImage() error {
230		return &BenchError{Kind: SeedFailed, Cause: "skopeo inspect did not find the image", Check: "check that the image exists"}
231	}
232	
233	func refusedImage() error {
234		return &BenchError{Kind: RegistryRefused, Cause: "a registry refused the skopeo call", Check: "check the credentials"}
235	}
