237	func nameTag(img DatasetImage) string { return img.Name + ":" + img.Tag }
238	
239	func sameCreds(got, want *Credentials) bool {
240		if got == nil || want == nil {
241			return got == want
242		}
243		return got.User == want.User && got.Password == want.Password
244	}
