246	func (c *seedCopier) lookup(ref ImageRef) (refInfo, bool) {
247		if c.index == nil {
248			c.index = map[string]refInfo{}
249			for _, img := range Dataset() {
250				switch img.Location {
251				case LocationHosted:
252					c.index[imageArg(nexusImageRef(*c.p, dockerHostedRepository, img))] = refInfo{whereHosted, img}
253				case LocationUpstream:
254					c.index[imageArg(upstreamImageRef(c.fwd.local, img))] = refInfo{whereUpstream, img}
255					c.index[imageArg(nexusImageRef(*c.p, dockerProxyRepository, img))] = refInfo{whereProxy, img}
256				}
257			}
258		}
259		info, ok := c.index[imageArg(ref)]
260		return info, ok
261	}
262	
263	// whereOf is the registry a copy touches: the docker side of it.
264	func (c *seedCopier) whereOf(refs ...ImageRef) (string, string) {
265		for _, r := range refs {
266			if r.Transport != "docker" {
267				continue
268			}
269			if info, ok := c.lookup(r); ok {
270				return info.where, nameTag(info.img)
271			}
272			return "unknown", r.Location
273		}
274		return "none", ""
275	}
