293	// reach fails the way a closed port-forward does.
294	func (c *seedCopier) reach(where string) error {
295		if where == whereUpstream && !c.fwd.active {
296			c.t.Errorf("the upstream was reached while the port-forward is not open")
297			return &BenchError{Kind: RegistryUnreachable, Cause: "connection refused", Check: "start the port-forward"}
298		}
299		return nil
300	}
301	
302	// read returns the manifest digest of ref the way a registry (or a layout) would.
303	func (c *seedCopier) read(ref ImageRef, creds *Credentials) (string, error) {
304		if ref.Transport == "oci" {
305			return c.readLayout(ref)
306		}
307		info, ok := c.lookup(ref)
308		if !ok || ref.Transport != "docker" {
309			c.t.Errorf("read of %s: not a reference of the data set", imageArg(ref))
310			return "", absentImage()
311		}
312		if err := c.reach(info.where); err != nil {
313			return "", err
314		}
315		if err := c.authorize(info.where, creds); err != nil {
316			return "", err
317		}
318		nt := nameTag(info.img)
319		switch info.where {
320		case whereUpstream:
321			if d, ok := c.upstream[nt]; ok {
322				return d, nil
323			}
324		case whereHosted:
325			if d, ok := c.hosted[nt]; ok {
326				return d, nil
327			}
328		case whereProxy:
329			if !info.img.PullThrough {
330				c.t.Errorf("F9: %s was read through docker-proxy, which caches it: only PullThrough images may be", nt)
331			}
332			if d, ok := c.proxyCache[nt]; ok {
333				return d, nil
334			}
335			if d, ok := c.upstream[nt]; ok {
336				c.preload(whereProxy, info.img, d)
337				return d, nil
338			}
339		}
340		return "", absentImage()
341	}
342	
343	// readLayout reads the digest of an image of the OCI layout "<dir>:<ref>".
344	func (c *seedCopier) readLayout(ref ImageRef) (string, error) {
345		i := strings.LastIndex(ref.Location, ":")
346		if i < 0 {
347			c.t.Errorf("oci reference %q has no image name", ref.Location)
348			return "", absentImage()
349		}
350		dir, name := ref.Location[:i], ref.Location[i+1:]
351		if !strings.HasPrefix(dir, c.tmp+string(os.PathSeparator)) {
352			c.t.Errorf("the layout %s is not in a temporary folder under TMPDIR (%s)", dir, c.tmp)
353		}
354		raw, err := os.ReadFile(filepath.Join(dir, "index.json"))
355		if err != nil {
356			c.t.Errorf("the layout is not readable when the copy starts: %v", err)
357			return "", absentImage()
358		}
359		var idx struct {
360			Manifests []struct {
361				Digest      string            `json:"digest"`
362				Annotations map[string]string `json:"annotations"`
363			} `json:"manifests"`
364		}
365		if err := json.Unmarshal(raw, &idx); err != nil {
366			c.t.Errorf("index.json of the layout is not JSON: %v", err)
367			return "", absentImage()
368		}
369		for _, m := range idx.Manifests {
370			if m.Annotations[annotationRefName] == name {
371				c.ociCopies++
372				return m.Digest, nil
373			}
374		}
375		c.t.Errorf("the layout holds no image called %q", name)
376		return "", absentImage()
377	}
