379	// Copy implements ImageCopier.
380	func (c *seedCopier) Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error {
381		c.t.Helper()
382		where, nt := c.whereOf(dst, src)
383		call := copyCall{src: src, dst: dst, opts: o, where: where}
384		c.copies = append(c.copies, call)
385		c.log.add("copy " + where + " " + nt)
386		if c.copyErr != nil {
387			if err := c.copyErr(len(c.copies), call); err != nil {
388				return err
389			}
390		}
391		if err := ctx.Err(); err != nil {
392			return &BenchError{Kind: Unclassified, Cause: "skopeo copy was interrupted", Check: "run the command again", Err: err}
393		}
394		if !o.PreserveDigests {
395			c.t.Errorf("copy of %s without PreserveDigests", nt)
396		}
397		for _, side := range []struct {
398			ref   ImageRef
399			creds *Credentials
400		}{{src, o.SrcCreds}, {dst, o.DestCreds}} {
401			if err := checkSide(side.ref, side.creds); err != nil {
402				c.t.Errorf("the real copier would refuse %s before any process: %v", imageArg(side.ref), err)
403				return err
404			}
405		}
406		digest, err := c.read(src, o.SrcCreds)
407		if err != nil {
408			return err
409		}
410		if !o.PreserveDigests {
411			sum := sha256.Sum256([]byte(digest))
412			digest = "sha256:" + hex.EncodeToString(sum[:])
413		}
414		return c.write(dst, src, digest, o.DestCreds)
415	}
416	
417	func (c *seedCopier) write(dst, src ImageRef, digest string, creds *Credentials) error {
418		switch dst.Transport {
419		case "dir":
420			if !strings.HasPrefix(dst.Location, c.tmp+string(os.PathSeparator)) {
421				c.t.Errorf("the pull-through target %s is not under TMPDIR (%s)", dst.Location, c.tmp)
422			}
423			return os.MkdirAll(dst.Location, 0o700)
424		case "docker":
425		default:
426			c.t.Errorf("destination transport %q", dst.Transport)
427			return absentImage()
428		}
429		info, ok := c.lookup(dst)
430		if !ok {
431			c.t.Errorf("write to %s: not a reference of the data set", imageArg(dst))
432			return absentImage()
433		}
434		if err := c.reach(info.where); err != nil {
435			return err
436		}
437		if info.where == whereProxy {
438			c.t.Errorf("a write through docker-proxy: it is a proxy, nothing is pushed to it")
439			return refusedImage()
440		}
441		if err := c.authorize(info.where, creds); err != nil {
442			return err
443		}
444		if src.Transport == "oci" && digest != info.img.Digest {
445			c.t.Errorf("the copy to %s %s would store %s, the data set says %s: the layout reference of another image was used",
446				info.where, nameTag(info.img), digest, info.img.Digest)
447		}
448		if info.where == whereUpstream {
449			c.upstream[nameTag(info.img)] = digest
450			return nil
451		}
452		c.preload(whereHosted, info.img, digest)
453		return nil
454	}
455	
456	// ManifestDigest implements ImageCopier.
457	func (c *seedCopier) ManifestDigest(_ context.Context, ref ImageRef, creds *Credentials) (string, error) {
458		where, nt := c.whereOf(ref)
459		call := digestCall{ref: ref, creds: creds, where: where}
460		c.digests = append(c.digests, call)
461		c.log.add("digest " + where + " " + nt)
462		if c.digestErr != nil {
463			if err := c.digestErr(call); err != nil {
464				return "", err
465			}
466		}
467		if err := checkSide(ref, creds); err != nil {
468			c.t.Errorf("the real copier would refuse %s before any process: %v", imageArg(ref), err)
469			return "", err
470		}
471		return c.read(ref, creds)
472	}
