509	func (c *seedCopier) setComponent(repo string, img DatasetImage, digest string) {
510		comp := fakeComponent{Name: img.Name, Version: img.Tag, Digest: digest}
511		list := c.listing[repo]
512		if i := slices.IndexFunc(list, func(x fakeComponent) bool { return x.Name == comp.Name && x.Version == comp.Version }); i >= 0 {
513			list[i] = comp
514		} else {
515			list = append(list, comp)
516		}
517		c.listing[repo] = list
518		c.publish(repo)
519	}
