632	// checkInvariants are the rules that hold after every call, success or failure.
633	func (e *seedEnv) checkInvariants(err error) {
634		e.t.Helper()
635		// Seed reads Nexus; it never writes to it, and always as the admin account.
636		for _, r := range e.b.nexus.Requests()[e.baseline:] {
637			if r.Method != http.MethodGet {
638				e.t.Errorf("Seed sent %s %s to Nexus: it only reads", r.Method, r.Path)
639			}
640			if r.User != adminUserID {
641				e.t.Errorf("Seed sent %s %s as %q, want the admin account", r.Method, r.Path, r.User)
642			}
643		}
644		// Seed reads the cluster and writes nothing (NX-02a: it never restores the upstream).
645		if len(e.kube.writes) != 0 {
646			e.t.Errorf("Seed wrote to the cluster: %q", e.kube.writes)
647		}
648		e.kube.requireNoPreflight()
649		// One port-forward per run, always stopped.
650		if len(e.fwd.calls) > e.runs {
651			e.t.Errorf("%d port-forwards for %d runs", len(e.fwd.calls), e.runs)
652		}
653		for _, call := range e.fwd.calls {
654			if want := (forwardCall{e.p.Namespace, "bench-upstream", 5000}); call != want {
655				e.t.Errorf("port-forward to %+v, want %+v", call, want)
656			}
657		}
658		if e.fwd.active {
659			e.t.Error("the port-forward is still open when Seed returns")
660		}
661		if opened := e.openedForwards(); e.fwd.stops < opened {
662			e.t.Errorf("%d forwards opened, stop called %d times", opened, e.fwd.stops)
663		}
664		// Temporary folders.
665		if left, rerr := os.ReadDir(e.tmp); rerr != nil || len(left) != 0 {
666			names := make([]string, 0, len(left))
667			for _, f := range left {
668				names = append(names, f.Name())
669			}
670			e.t.Errorf("temporary files left under TMPDIR: %v (%v)", names, rerr)
671		}
672		e.requireQuiet(err)
673	}
674	
675	// openedForwards counts the forwards that succeeded.
676	func (e *seedEnv) openedForwards() int {
677		n := 0
678		for _, ev := range e.log.snapshot() {
679			if ev == "forward" {
680				n++
681			}
682		}
683		if e.fwd.err != nil || n > len(e.fwd.calls) {
684			return 0
685		}
686		return n
687	}
