689	// requireQuiet fails when a password is in what Seed said, in its error, or in
690	// anything a process would be given on its command line.
691	func (e *seedEnv) requireQuiet(err error) {
692		e.t.Helper()
693		texts := map[string]string{"output": e.out.String(), "kubectl": strings.Join(e.kube.lines, "\n")}
694		if err != nil {
695			texts["error"] = err.Error()
696		}
697		var argv []string
698		for _, c := range e.cp.copies {
699			argv = append(argv, imageArg(c.src), imageArg(c.dst))
700		}

700		}
701		for _, c := range e.cp.digests {
702			argv = append(argv, imageArg(c.ref))
703		}
704		for _, f := range e.fwd.calls {
705			argv = append(argv, f.namespace, f.service, fmt.Sprint(f.port))
706		}
707		texts["argv"] = strings.Join(argv, "\n")
708		for label, text := range texts {
709			for _, secret := range e.secrets() {
710				if secret != "" && strings.Contains(text, secret) {
711					e.t.Errorf("the %s contains a password (%d characters): %q", label, len(secret), text)
712				}
713			}
714		}
715	}
