780	// wantCopy is one expected Copy.
781	type wantCopy struct {
782		srcTransport string    // "oci" or "docker"
783		src          *ImageRef // for docker sources
784		dst          ImageRef
785		dirDst       bool
786		srcCreds     *Credentials
787		destCreds    *Credentials
788	}
