790	// fullSequence is the Copy calls of a first run, in order.
791	func (e *seedEnv) fullSequence() []wantCopy {
792		admin, pull := e.cp.admin, e.cp.pull
793		var out []wantCopy
794		for _, img := range imagesIn(LocationUpstream) {
795			out = append(out, wantCopy{srcTransport: "oci", dst: upstreamImageRef(e.fwd.local, img)})
796		}
797		for _, img := range imagesIn(LocationHosted) {
798			out = append(out, wantCopy{srcTransport: "oci", dst: nexusImageRef(e.p, dockerHostedRepository, img), destCreds: &admin})
799		}
800		for _, img := range pullThrough() {
801			src := nexusImageRef(e.p, dockerProxyRepository, img)
802			out = append(out, wantCopy{srcTransport: "docker", src: &src, dirDst: true, srcCreds: &pull})
803		}
804		return out
805	}
