807	func (e *seedEnv) requireCopies(want []wantCopy) {
808		e.t.Helper()
809		got := e.cp.copies
810		if len(got) != len(want) {
811			e.t.Fatalf("%d copies, want %d:\n%s", len(got), len(want), describeCopies(got))
812		}
813		for i, w := range want {
814			g := got[i]
815			switch {
816			case g.src.Transport != w.srcTransport:
817				e.t.Errorf("copy #%d: source transport %q, want %q", i+1, g.src.Transport, w.srcTransport)
818			case w.src != nil && g.src != *w.src:
819				e.t.Errorf("copy #%d: source %v, want %v", i+1, g.src, *w.src)
820			}
821			if w.dirDst {
822				if g.dst.Transport != "dir" || !strings.HasPrefix(g.dst.Location, e.tmp) {
823					e.t.Errorf("copy #%d: destination %v, want a dir under %s", i+1, g.dst, e.tmp)
824				}
825			} else if g.dst != w.dst {
826				e.t.Errorf("copy #%d: destination %v, want %v", i+1, g.dst, w.dst)
827			}
828			if !sameCreds(g.opts.SrcCreds, w.srcCreds) || !sameCreds(g.opts.DestCreds, w.destCreds) {
829				e.t.Errorf("copy #%d: source credentials set=%t, destination credentials set=%t, want %t and %t",
830					i+1, g.opts.SrcCreds != nil, g.opts.DestCreds != nil, w.srcCreds != nil, w.destCreds != nil)
831			}
832			if !g.opts.PreserveDigests {
833				e.t.Errorf("copy #%d: no --preserve-digests", i+1)
834			}
835		}
836	}
