838	func describeCopies(calls []copyCall) string {
839		var b strings.Builder
840		for i, c := range calls {
841			fmt.Fprintf(&b, "  %d. %s -> %s\n", i+1, imageArg(c.src), imageArg(c.dst))
842		}
843		return b.String()
844	}
