846	// requirePhases checks the order of the events: every read of the upstream is
847	// inside the port-forward, and the upstream, then docker-hosted, then docker-proxy
848	// are done one after the other.
849	func requirePhases(t *testing.T, events []string) {
850		t.Helper()
851		rank := map[string]int{whereUpstream: 0, whereHosted: 1, whereProxy: 2}
852		forward, stop := slices.Index(events, "forward"), slices.Index(events, "stop")
853		last := -1
854		for i, ev := range events {
855			fields := strings.Fields(ev)
856			if fields[0] != "copy" && fields[0] != "digest" {
857				continue
858			}
859			r, ok := rank[fields[1]]
860			if !ok {
861				t.Errorf("event %q touches nothing of the data set", ev)
862				continue
863			}
864			if r < last {
865				t.Errorf("event %q comes after an event of a later registry", ev)
866			}
867			last = max(last, r)
868			if fields[1] == whereUpstream && (forward < 0 || i < forward || (stop >= 0 && i > stop)) {
869				t.Errorf("event %q is not inside the port-forward (forward at %d, stop at %d, event at %d)", ev, forward, stop, i)
870			}
871			if fields[1] != whereUpstream && (stop < 0 || i < stop) {
872				t.Errorf("event %q comes before the port-forward is stopped (stop at %d, event at %d)", ev, stop, i)
873			}
874		}
875	}
876	
877	// requireListing checks what a repository lists, through the REST client.
878	func (e *seedEnv) requireListing(repo string, want []DatasetImage) {
879		e.t.Helper()
880		c := e.b.adminClient()
881		got, err := e.b.list(c, repo)
882		if err != nil {
883			e.t.Fatalf("listComponents(%s): %v", repo, err)
884		}
885		have := map[string]string{}
886		for _, comp := range got {
887			have[comp.Name+":"+comp.Version] = comp.Digest
888		}
889		if len(have) != len(want) {
890			e.t.Errorf("%s lists %v, want %d images", repo, have, len(want))
891		}
892		for _, img := range want {
893			if d, ok := have[nameTag(img)]; !ok || d != img.Digest {
894				e.t.Errorf("%s lists %s with digest %q, want %q", repo, nameTag(img), d, img.Digest)
895			}
896		}
897	}
