899	// ---- the first run -------------------------------------------------------------
900	
901	func TestSeedFirstRun(t *testing.T) {
902		for _, tt := range []struct {
903			name   string
904			mutate func(*Params)
905		}{
906			{"default ports", func(*Params) {}},
907			{"another HTTP NodePort", func(p *Params) { p.HTTPNodePort = 31999 }},
908		} {
909			t.Run(tt.name, func(t *testing.T) {
910				e := newSeedEnv(t, readyUpstream(), tt.mutate)
911				res := e.mustRun()
912	
913				// The exact sequence of copies: the upstream images, then docker-hosted,
914				// then the pull-through, each in the order of the data set.
915				e.requireCopies(e.fullSequence())
916				requirePhases(t, e.log.snapshot())
917				if e.cp.ociCopies != len(imagesIn(LocationUpstream))+len(imagesIn(LocationHosted)) {
918					t.Errorf("%d copies read the layout, want one per pushed image", e.cp.ociCopies)
919				}
920	
921				// The state of the cluster is read before the port-forward opens.
922				events := e.log.snapshot()
923				forward := slices.Index(events, "forward")
924				for i, ev := range events {
925					if ev == "kubectl" && i > forward {
926						t.Errorf("kubectl is called after the port-forward opened (event %d)", i)
927					}
928				}
929				if forward < 0 || !slices.Contains(events[:forward], "kubectl") {
930					t.Errorf("the upstream was not read before the port-forward: %v", events)
931				}
932	
933				// Every docker reference is on the loopback, on the forward or the NodePort.
