96	// Copy implements ImageCopier: `skopeo copy` of src to dst. A docker reference
97	// whose host is not the loopback is refused before any process starts.
98	func (c *skopeoCopier) Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error {
99		if err := checkSide(src, o.SrcCreds); err != nil {
100			return err
101		}
102		if err := checkSide(dst, o.DestCreds); err != nil {
103			return err
104		}
105		w, err := newSkopeoWorkdir()
106		if err != nil {
107			return err
108		}
109		defer w.remove()
110	
111		args := []string{"--policy", w.policy, "copy"}
112		if o.PreserveDigests {
113			args = append(args, "--preserve-digests")
114		}
115		for _, side := range []struct {
116			flagPrefix string
117			ref        ImageRef
118			creds      *Credentials
119		}{{"--src-", src, o.SrcCreds}, {"--dest-", dst, o.DestCreds}} {
120			flags, err := w.sideFlags(side.flagPrefix, side.ref, side.creds)
121			if err != nil {
122				return err
123			}
124			args = append(args, flags...)
125		}
126		args = append(args, imageArg(src), imageArg(dst))
127	
128		if _, err := c.run(ctx, w, "copy", args, 0); err != nil {
129			return err
130		}
131		return nil
132	}
