169	// run starts skopeo with args in the environment of w and returns its stdout
170	// (at most stdoutMax bytes; with 0 the stdout is dropped). Nothing skopeo prints
171	// reaches the error: the stderr only picks its kind.
172	func (c *skopeoCopier) run(ctx context.Context, w *skopeoWorkdir, op string, args []string, stdoutMax int) ([]byte, error) {
173		cmd := exec.CommandContext(ctx, c.path, args...) //nolint:gosec // the binary is the skopeo found on PATH and the references were checked by checkSide
174		cmd.Env = skopeoEnvironment(w.registriesConf)
175		cmd.WaitDelay = skopeoKillDelay
176		stdout, stderr := newCapWriter(stdoutMax), newCapWriter(skopeoStderrMax)
177		cmd.Stdout, cmd.Stderr = stdout, stderr
178	
179		runErr := cmd.Run()
180		if runErr == nil {
181			if stdoutMax > 0 && stdout.over {
182				return nil, &BenchError{
183					Kind:  SeedFailed,
184					Cause: "the manifest is larger than the 4 MiB registries accept",
185					Check: "run `skopeo inspect --raw` on the same reference by hand",
186				}
187			}
188			return stdout.buf.Bytes(), nil
189		}
190		if ctxErr := ctx.Err(); ctxErr != nil {
191			kind := Unclassified
192			if errors.Is(ctxErr, context.DeadlineExceeded) {
193				kind = Deadline
194			}
195			return nil, &BenchError{
196				Kind:  kind,
197				Cause: fmt.Sprintf("skopeo %s was interrupted", op),
198				Check: "run the command again",
199				Err:   ctxErr,
200			}
201		}
202		return nil, skopeoFailure(op, classifySkopeo(stderr.buf.String()), runErr)
203	}
