205	// skopeoFailure builds the error of a skopeo that exited with a failure.
206	func skopeoFailure(op string, kind ErrKind, runErr error) *BenchError {
207		be := &BenchError{Kind: kind, Err: runErr}
208		switch kind {
209		case RegistryUnreachable:
210			be.Cause = fmt.Sprintf("skopeo %s could not reach a registry", op)
211			be.Check = "check that the port-forward is running and the registry answers on its port"
212		case RegistryRefused:
213			be.Cause = fmt.Sprintf("a registry refused the skopeo %s", op)
214			be.Check = "check the bench credentials in the secrets file and the privileges of the account"
215		case SeedFailed:
216			be.Cause = fmt.Sprintf("skopeo %s did not find the image", op)
217			be.Check = "check that the image and its tag exist in the source registry"
218		default:
219			be.Cause = fmt.Sprintf("skopeo %s failed", op)
220			be.Check = "run the same skopeo command by hand to see what it says"
221		}
222		return be
223	}
