236	// and a docker reference whose host is not the loopback (TLS verification is
237	// switched off for every docker reference, so the host is the only protection).
238	func checkSide(r ImageRef, creds *Credentials) error {
239		switch r.Transport {
240		case "oci", "dir":
241			if creds != nil {
242				return &BenchError{
243					Kind:  Unclassified,
244					Cause: "credentials were given for an image that is not in a registry",
245					Check: "give credentials only for a docker reference",
246				}
247			}
248			return nil
249		case "docker":
250			host, name, hasName := strings.Cut(r.Location, "/")
251			if !hasName || name == "" || !loopbackRegistry(host) {
252				return &BenchError{
253					Kind:  Unclassified,
254					Cause: "the bench only talks to a registry on the loopback, with a repository name: TLS verification is off for it",
255					Check: "reach the registry through the port-forward and give 127.0.0.1:<port>/<name>[:<tag>]",
256				}
257			}
258			return nil
259		}
260		return &BenchError{
261			Kind:  Unclassified,
262			Cause: "the image transport is not one of oci, dir and docker",
263			Check: "give a reference whose transport is oci, dir or docker",
264		}
265	}
