275	// loopbackRegistry tells whether hostPort ("127.0.0.1:5000", "[::1]:5000") is
276	// one of the two loopback literals and nothing else ("localhost" is not: it
277	// resolves through the host's configuration). It parses the host and the
278	// port instead of testing a prefix, so "127.0.0.1@evil.com",
279	// "127.0.0.1.evil.com" and "127.0.0.1:5000@evil.com" are not the loopback.
280	func loopbackRegistry(hostPort string) bool {
281		host := hostPort
282		if h, p, err := net.SplitHostPort(hostPort); err == nil {
283			if n, err := strconv.Atoi(p); err != nil || n < 1 || n > 65535 || strconv.Itoa(n) != p {
284				return false
285			}
286			host = h
287			if strings.HasPrefix(hostPort, "[") {
288				return host == "::1"
289			}
290		} else if strings.HasPrefix(hostPort, "[") && strings.HasSuffix(hostPort, "]") {
291			return hostPort == "[::1]"
292		}
293		return host == "127.0.0.1"
294	}
